import{z as s,x as A,o as e,c as B,q as o,j as i,D as a,d as l,s as r,S as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"开源生态收束","description":"","frontmatter":{"title":"开源生态收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/eco-map.md","filePath":"llm/eco-map.md","lastUpdated":1791413859000}'),p={name:"llm/eco-map.md"};function d(m,E,c,g,D,_){const n=A("Mermaid");return e(),B("div",null,[E[2]||(E[2]=o('<h1 id="开源生态收束" tabindex="-1">开源生态收束 <a class="header-anchor" href="#开源生态收束" aria-label="Permalink to &quot;开源生态收束&quot;">​</a></h1><div class="epigraph"><p>发布不是把权重推上平台的那一天，而是生态里的陌生人此后每一次引用、合并与复算时，都还查得到账的那十几年。</p><footer>—— 据 OSI 开源定义、各模型许可文本与 Llama 3、DeepSeek-V3、Qwen2.5、OLMo 发布实践，按本课程整理</footer></div><p><a href="/llm/eco-repro-report-writing">上一课</a>把技术报告写成带声明层级的契约。至此零件齐了：谱系与五段读法管许可怎么选怎么读，血缘台账管衍生怎么记账，卡与元数据管发布包怎么配，版本与分支管地址怎么钉，报分纪律与三角化管数字怎么站住，报告模块管配方怎么承诺。本课把它们装配成一张地图与一张决策单。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>发布工程的决策散在七处：选哪一档许可、条款怎么读、合并产物挂什么、卡配到什么程度、版本怎么钉、分数怎么报、报告写到哪层。各自局部最优会互相拆台：没有台账的卡写不出血缘；没有版本纪律的报分无从复算；没有层级声明的报告让下游把复述当复现。收束要给的是先后顺序与跨版本不动的部分——许可会改版、榜单会换代、平台会换界面，地图的骨架得比这些都活得久。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>发布方决策单</strong>，按依赖排序：</p><ol><li><strong>定档</strong>：按控制与采用五条轴选许可档位，自定义条款先想维护成本。</li><li><strong>写清单</strong>：对官方文本跑五段读法，合规清单进仓库。</li><li><strong>立台账</strong>：血缘、revision、量化源成对登记，口径按最严输入。</li><li><strong>配发布包</strong>：权重、元数据、模型卡、数据卡四件齐，<code>license</code> 字段与文本一致。</li><li><strong>钉版本</strong>：tag 与 changelog，变体各占地址，破坏性变更单独发版。</li><li><strong>报分</strong>：协议披露、开放配置、输赢同表，独立信号交叉引用。</li><li><strong>写报告</strong>：声明层级先行，模块 diff 演进，负结果进附录。</li></ol><p>使用方把同一张单倒过来读：先查 license 字段与条款文本、再查血缘与 revision、再验报分协议，最后才决定接不接。<span class="marginnote">四条不变量像房屋的承重墙：装修风格——许可改版、榜单换代、平台换界面——随便换，承重墙不动房子就不塌。判断一个团队的发布流程能不能经得起几年时间，不用看它工具多花哨，就看许可一致性、最严传播、不可变锚、协议披露这四条有没有被绕开。</span></p>',9)),(e(),i(t,null,{default:a(()=>[r(n,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E5%AE%9A%E6%A1%A3%EF%BC%9A%E4%BA%94%E6%9D%A1%E8%BD%B4%22%5D%20--%3E%20S2%5B%22%E4%BA%94%E6%AE%B5%E8%AF%BB%E6%B3%95%E5%87%BA%E5%90%88%E8%A7%84%E6%B8%85%E5%8D%95%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E8%A1%80%E7%BC%98%E5%8F%B0%E8%B4%A6%E4%B8%8E%E6%9C%80%E4%B8%A5%E5%8F%A3%E5%BE%84%22%5D%0A%20%20S3%20--%3E%20S4%5B%22%E5%9B%9B%E4%BB%B6%E5%8F%91%E5%B8%83%E5%8C%85%22%5D%0A%20%20S4%20--%3E%20S5%5B%22tag%E3%80%81changelog%20%E4%B8%8E%E5%8F%98%E4%BD%93%E5%9C%B0%E5%9D%80%22%5D%0A%20%20S5%20--%3E%20S6%5B%22%E5%8D%8F%E8%AE%AE%E6%8A%AB%E9%9C%B2%E4%B8%8E%E4%B8%89%E8%A7%92%E5%8C%96%E6%8A%A5%E5%88%86%22%5D%0A%20%20S6%20--%3E%20S7%5B%22%E5%88%86%E5%B1%82%E6%8A%A5%E5%91%8A%E4%B8%8E%E8%B4%9F%E7%BB%93%E6%9E%9C%22%5D%0A%20%20INV%5B%22%E5%9B%9B%E6%9D%A1%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%20-.-%3E%20S2%0A%20%20INV%20-.-%3E%20S4%0A%20%20INV%20-.-%3E%20S6%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>地图的骨架是四条不变量。<strong>许可一致性</strong>：卡上的字段、正文与条款文本必须互相印证，任何一处打架，下游的自动化管线会替你选最坏的那种解读。<strong>最严传播</strong>：血缘里最严格的输入定义输出口径，模糊不是豁免而是风险。<strong>不可变锚</strong>：评测、回滚、卡的对应全靠 revision 哈希，追 main 的管线没有资格谈复现。<strong>协议披露</strong>：每个对外数字带 harness 与解码，复算成本决定公信力。谱系会漂移——Llama 从研究许可走到社区条款，榜单从裸胜率走到长度控制——参数全换，这四条不动。若只做三件事：生产与评测一律 pin 哈希；<code>license</code> 字段与条款文本对齐；每个对外数字带协议列。<span class="marginnote">「pin 哈希」就是把依赖钉死在某个具体版本（revision）上，像下锚。模型平台上的 main 分支随时在变，今天跑通的评测，明天同一命令拿到的可能已是另一份权重；pin 住之后，一年后任何人重跑，拿到的都是同一个文件。初学者常以为「模型名没变东西就没变」——实际上同一名下的权重、卡与许可都可能被静默更新。</span>本课程见过的大多数发布翻车，在这三步就被拦住。</p><p><span class="marginnote">把七步决策单贴进发布 checklist 仓库，与合规清单、血缘台账同一处维护——散在群聊里的发布决策，半年后就成了没人认领的账。</span></p><p>同一张单使用方倒着读，就是一套接入前的验收流程：</p>',4)),(e(),i(t,null,{default:a(()=>[r(n,{id:"mermaid-72",class:"mermaid",graph:"flowchart%20LR%0A%20%20SEE%5B%22%E7%9C%8B%E4%B8%AD%E4%B8%80%E4%B8%AA%E5%BC%80%E6%BA%90%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20C1%5B%22%E6%9F%A5%20license%20%E5%AD%97%E6%AE%B5%E4%B8%8E%E6%9D%A1%E6%AC%BE%E6%96%87%E6%9C%AC%E4%B8%80%E8%87%B4%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E6%9F%A5%20base_model%20%E9%93%BE%E4%B8%8E%E8%A1%80%E7%BC%98%20revision%22%5D%0A%20%20C2%20--%3E%20C3%5B%22%E6%9F%A5%E6%8A%A5%E5%88%86%E5%8D%8F%E8%AE%AE%E4%B8%8E%E5%8F%AF%E5%A4%8D%E7%AE%97%E9%85%8D%E7%BD%AE%22%5D%0A%20%20C3%20--%3E%20Q%7B%22%E4%B8%89%E9%A1%B9%E9%83%BD%E8%BF%87%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20ADOPT%5B%22%E6%8E%A5%E5%85%A5%E5%B9%B6%20pin%20revision%20%E5%93%88%E5%B8%8C%22%5D%0A%20%20Q%20--%3E%7C%E5%90%A6%7C%20ASK%5B%22%E9%97%AE%E5%8F%91%E5%B8%83%E6%96%B9%EF%BC%8C%E6%88%96%E6%8D%A2%E5%BA%95%E5%BA%A7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=o('<p><span class="marginnote">为什么「license 字段与条款打架」这么严重？下游的自动化工具——包管理器、合规扫描器——通常只读字段、不读正文。字段写 MIT、正文却是社区许可时，工具会替你按 MIT 放行；等人工发现不一致，产品可能已经发出去几个月了。这就是「管线会替你选最坏的那种解读」的含义：机器不会替你质疑输入。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这张地图有它不覆盖的两翼：托管 API 的服务条款与权重许可是两套合同，本课程只管后者；跨境部署、专利与商标的交叉是专业法律审查的事，五段读法不替代律师。地图也不断言任何一份具体许可「安全」：法辖区与个案能把稳妥变冒险，地图给的是流程，不是结论。发布之后的另一半生态——下游怎么用这些权重做微调、合并与蒸馏——属于训练课程的范围；本课程把账记清、把地址钉牢，让那边的人接得动。发布工程做到头，是把「信任发布方」换成「任何人可审计」：许可有谱系、条款有清单、数字有协议、配方有层级，生态才长得动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发布方七步决策单：定档、清单、台账、发布包、版本、报分、报告；使用方倒着读同一张单。</li><li>四条不变量：许可一致性、最严传播、不可变锚、协议披露；参数换代，顺序不动。</li><li>三件高频拦错事：pin 哈希、对齐 license 字段、报分带协议列。</li><li>模糊不是豁免：血缘按最严输入记账，缺失的章节按「不可审计」处理。</li><li>本课程管权重许可与发布，不管 API 服务条款，也不替代法律审查。</li><li>出处：OSI 开源定义；Llama 社区许可、Gemma 条款、Apache 2.0、MIT 文本；Llama 3、DeepSeek-V3、Qwen2.5、OLMo 发布物，按本课程整理。</li></ul>',5))])}const S=s(p,[["render",d]]);export{C as __pageData,S as default};
